        System.out.println("'A' + 1 = " + c);
    }
}

public class Main {
    public static void main(String[] args) {
        int max = Integer.MAX_VALUE;
        System.out.println("MAX + 1        = " + (max + 1)); // wraps silently
        System.out.println("abs(MIN_VALUE) = " + Math.abs(Integer.MIN_VALUE));
        int a = 100000, b = 100000;
        System.out.println("int  a*b       = " + (a * b));       // overflowed
        System.out.println("long a*b       = " + ((long) a * b)); // cast first
        try {
            Math.addExact(max, 1); // throws instead of wrapping
        } catch (ArithmeticException e) {
            System.out.println("addExact threw: " + e.getMessage());
        }
        // Result of 13! looks fine as positive but is wrong
        int f = 1;
        for (int i = 2; i <= 13; i++) f *= i;
        System.out.println("13! as int     = " + f + " (true value 6227020800)");
    }
}

public class Main {
    public static void main(String[] args) {
        byte b = 1;
        // b = b + 1;      // does not compile: b + 1 is an int
        b += 1;            // compiles: means b = (byte)(b + 1)
        System.out.println("b = " + b);
        short s = 10;
        s *= 10000;        // hidden narrowing cast loses bits
        System.out.println("short s = " + s);
        int big = 130;
        System.out.println("(byte) 130 = " + (byte) big);
        System.out.println("(int) 3.99  = " + (int) 3.99);
        System.out.println("(int) -3.99 = " + (int) -3.99);   // toward zero
        System.out.println("(int) NaN   = " + (int) Double.NaN);
        System.out.println("(int) 1e20  = " + (int) 1e20);    // saturates
        long l = 123456789012L;
        float f = l;       // widening, but precision is lost
        System.out.println("long to float = " + (long) f);
    }
}

public class Main {
    static long work(int n) {
        long sum = 0;
        for (int i = 0; i < n; i++) sum += i % 7;
        return sum;
    }

    public static void main(String[] args) {
        // The same method is timed several times: early runs are interpreted,
        // later runs use JIT-compiled code. Timings vary by machine.
        for (int round = 1; round <= 5; round++) {
            long t0 = System.nanoTime();
            long r = work(20_000_000);
            long ms = (System.nanoTime() - t0) / 1_000_000;
            System.out.println("round " + round + ": result=" + r + " time=" + ms + " ms");
        }
        // the result is identical every round; only the time changes
    }
}

public class Main {
    public static void main(String[] args) {
        int i = 5;
        i = i++;           // saved 5, i becomes 6, then 5 is stored back
        System.out.println("i = i++        -> " + i);
        int a = 5;
        a += a++;          // 5 + 5 = 10
        System.out.println("a += a++       -> " + a);
        int j = 5;
        j = j++ + ++j;     // 5 + 7
        System.out.println("j = j++ + ++j  -> " + j);
        int x = 5;
        int y = x++ + ++x * x--; // 5 + 7 * 7
        System.out.println("y = " + y + ", x = " + x);
        int[] arr = new int[3];
        int k = 0;
        arr[k] = k = 2;    // index evaluated first (0)
        System.out.println("arr[0]=" + arr[0] + " arr[2]=" + arr[2] + " k=" + k);
    }
}

import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    public static void main(String[] args) {
        double d = 0.1 + 0.2;
        System.out.println("0.1 + 0.2 = " + d + " equal to 0.3? " + (d == 0.3));
        System.out.println("close enough? " + (Math.abs(d - 0.3) < 1e-9));
        // Build BigDecimal from Strings, not from doubles
        BigDecimal sum = new BigDecimal("0.1").add(new BigDecimal("0.2"));
        System.out.println("BigDecimal sum = " + sum + " equals 0.3? " + sum.equals(new BigDecimal("0.3")));
        System.out.println("new BigDecimal(0.1) = " + new BigDecimal(0.1));
        // equals cares about scale, compareTo does not
        System.out.println("1.0 equals 1.00? " + new BigDecimal("1.0").equals(new BigDecimal("1.00")));
        System.out.println("1.0 compareTo 1.00 = " + new BigDecimal("1.0").compareTo(new BigDecimal("1.00")));
        // Money in cents as long
        long cents = 1999 * 3;
        System.out.println("3 items = " + cents / 100 + "." + cents % 100);
        System.out.println("2.5 HALF_EVEN = " + new BigDecimal("2.5").setScale(0, RoundingMode.HALF_EVEN));
        System.out.println("3.5 HALF_EVEN = " + new BigDecimal("3.5").setScale(0, RoundingMode.HALF_EVEN));
    }
}

public class Main {
    public static void main(String[] args) {
        String s = "A\uD83D\uDE00B"; // A, grinning face emoji, B
        System.out.println("length()         = " + s.length());                       // chars
        System.out.println("codePointCount   = " + s.codePointCount(0, s.length())); // real characters
        System.out.println("char at 1 is high surrogate? " + Character.isHighSurrogate(s.charAt(1)));
        System.out.println("code point at 1  = U+" + Integer.toHexString(s.codePointAt(1)).toUpperCase());
        // Iterate by code point, not by char
        s.codePoints().forEach(cp -> System.out.println("cp " + cp + " uses " + Character.charCount(cp) + " char(s)"));
        // Safe reverse
        System.out.println("reversed ok: " + new StringBuilder(s).reverse().codePointCount(0, 4));
        // Truncate to 2 code points without splitting a pair
        int end = s.offsetByCodePoints(0, 2);
        System.out.println("first 2 chars = " + s.substring(0, end).length() + " UTF-16 units");
    }
}

public class Main {
    static { System.out.println("1. class initialized (static block)"); }

    public static void main(String[] args) throws Exception {
        System.out.println("2. main starts, args.length = " + args.length);
        Runtime.getRuntime().addShutdownHook(new Thread(() ->
            System.out.println("5. shutdown hook runs")));
        Thread t = new Thread(() -> {
            try { Thread.sleep(200); } catch (InterruptedException e) { }
            System.out.println("4. non-daemon thread finishes");
        });
        t.start(); // JVM waits for this thread even after main returns
        System.out.println("3. main returns, JVM still alive");
    }
}

public class Main {
    static int depth = 0;

    static void recurse() {
        depth++;
        recurse(); // no base case
    }

    public static void main(String[] args) {
        try {
            recurse();
        } catch (StackOverflowError e) {
            System.out.println("StackOverflowError caught, depth > 1000? " + (depth > 1000));
        }
        try {
            long[] huge = new long[Integer.MAX_VALUE]; // bigger than the VM allows
            System.out.println(huge.length);
        } catch (OutOfMemoryError e) {
            System.out.println("OutOfMemoryError caught: " + (e.getMessage().startsWith("Requested array size")
                || e.getMessage().startsWith("Java heap space")));
        }
        System.out.println("max heap known? " + (Runtime.getRuntime().maxMemory() > 0));
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("-8 >> 1  = " + (-8 >> 1));   // sign copied in
        System.out.println("-8 >>> 1 = " + (-8 >>> 1));  // zeros come in
        System.out.println("1 << 33  = " + (1 << 33));   // distance masked to 5 bits -> 1 << 1
        int low = 1_500_000_000, high = 2_000_000_000;
        int bad = (low + high) / 2;               // low+high overflows to negative
        int good1 = low + (high - low) / 2;
        int good2 = (low + high) >>> 1;           // unsigned shift repairs the wrapped sum
        System.out.println("bad   mid = " + bad);
        System.out.println("good1 mid = " + good1);
        System.out.println("good2 mid = " + good2);
        byte b = -1;
        b >>>= 4;                                 // promoted to int, shifted, narrowed back
        System.out.println("byte -1 >>>= 4 -> " + b);
    }
}

public class Main {
    public static void main(String[] args) {
        long[] ids = {2_147_483_647L, 2_147_483_648L, 4_294_967_296L + 5, 5L};
        for (long id : ids) {
            int narrowed = (int) id; // keeps only the low 32 bits
            System.out.println(id + " -> " + narrowed);
        }
        // id and id + 2^32 collide
        long a = 5L, b = 5L + (1L << 32);
        System.out.println("collision? " + ((int) a == (int) b));
        // Math.toIntExact fails loudly instead
        try {
            Math.toIntExact(b);
        } catch (ArithmeticException e) {
            System.out.println("toIntExact: " + e.getMessage());
        }
        // 2^53 limit for JavaScript numbers
        long js = (1L << 53) + 1;
        System.out.println("as double: " + (long) (double) js + " vs " + js);
    }
}
